import '../../../core/networking/player_api_client.dart';
class SupportApi { final PlayerApiClient client; SupportApi(this.client); Future<List<Map<String,dynamic>>> tickets() async { final r=await client.get('/support/tickets'); final data=Map<String,dynamic>.from(r.data as Map)['data'] as List; return data.map((e)=>Map<String,dynamic>.from(e as Map)).toList(); } Future<Map<String,dynamic>> ticket(String id) async { final r=await client.get('/support/tickets/$id'); return Map<String,dynamic>.from(Map<String,dynamic>.from(r.data as Map)['data'] as Map); } Future<Map<String,dynamic>> create({required String category,required String subject,required String message}) async { final r=await client.post('/support/tickets',data:{'category':category,'subject':subject,'message':message}); return Map<String,dynamic>.from(Map<String,dynamic>.from(r.data as Map)['data'] as Map); } Future<void> sendMessage(String id,String message) async { await client.post('/support/tickets/$id/messages',data:{'message':message}); } }
